const input = $json ?? {};
const decision = String(input.decision ?? input.negotiation_decision ?? '').toLowerCase();
const dealId = input.deal_id ?? null;
const leadId = input.lead_id ?? null;
const propertyId = input.property_id ?? null;
const dynamicMao = Number(input.dynamic_mao ?? input.adjusted_mao ?? input.mao);
const offerPrice = input.offer_price == null ? null : Number(input.offer_price);
const seller = input.seller ?? {};
const channel = String(input.channel ?? input.preferred_channel ?? '').toLowerCase();
const recipient = String(input.recipient ?? seller.phone ?? seller.email ?? input.seller_phone ?? input.seller_email ?? '').trim();
const dnc = Boolean(input.dnc ?? input.do_not_contact ?? false);
const blockers = Array.isArray(input.blockers) ? input.blockers : [];
const assetType = String(input.asset_type ?? input.property_type ?? 'residential').toLowerCase();
const identityComplete = Boolean(dealId && leadId && propertyId);
const maoValid = Number.isFinite(dynamicMao) && dynamicMao > 0;
const offerValid = offerPrice == null || (Number.isFinite(offerPrice) && offerPrice > 0);
const channelValid = ['sms','email'].includes(channel);
const recipientValid = Boolean(recipient);
const hardBlock = dnc || blockers.length > 0;
let action = 'needs_review'; let nextWorkflow = 'WF-126'; let reason = 'Decision requires review before external action.'; let dispatchReady = false; let reengagement = false; let humanReviewRequired = true;
if (hardBlock) { action = dnc ? 'dnc_blocked' : 'blocked'; reason = dnc ? 'Seller is on DNC; no outbound communication permitted.' : 'Active blocker prevents seller communication.'; }
else if (!identityComplete || !maoValid || !offerValid || !channelValid || !recipientValid) { action = 'incomplete'; reason = 'Required deal identity, MAO, offer, channel, or recipient data is missing/invalid.'; nextWorkflow = 'WF-339'; }
else if (['contract_decision_ready','accept_counteroffer_contract_review','contract_ready'].includes(decision)) {
  if (offerPrice != null && offerPrice > dynamicMao) { action = 'mao_violation_blocked'; reason = 'Contract/offer price exceeds dynamic MAO; dispatch is prohibited.'; nextWorkflow = 'WF-339'; }
  else { action = 'contract_review_required'; reason = 'Contract path is ready for human authorization before signature launch.'; nextWorkflow = 'WF-321'; }
}
else if (['near_mao_controlled_review','above_mao_revised_offer_or_walk_away','clarification_response'].includes(decision)) {
  action = 'revised_offer_review'; reason = 'Revised seller response requires controlled review before dispatch.'; dispatchReady = false; nextWorkflow = 'WF-334'; }
else if (['rejection_reengagement','timeout_reengagement','walk_away_or_reengage'].includes(decision)) {
  action = 'reengagement_ready'; reengagement = true; reason = 'Seller outcome requires controlled re-engagement.'; nextWorkflow = 'WF-261'; }
else { action = 'needs_review'; nextWorkflow = 'WF-339'; reason = 'WF-340 received an unsupported decision state.'; }
const assetStrategy = { residential:'Residential wholesale economics; 70% rule is secondary reference only.', multifamily:'Multifamily economics; prioritize NOI, cap rate/value evidence, debt and buyer demand.', land:'Land economics; prioritize zoning, utilities, access, topography, flood risk, land comps and development potential.', commercial:'Commercial economics; prioritize income/value evidence, lease/tenant factors, financing and exit demand.' }[assetType] ?? 'Asset-specific economics required; 70% rule is secondary reference only.';
const dispatchId = dispatchReady ? 'wf340-' + String(dealId) + '-' + String(offerPrice ?? 'na') + '-' + channel : null;
const idempotencyKey = dispatchReady ? 'WF-340:' + String(dealId) + ':' + String(offerPrice ?? 'na') + ':' + channel : null;
const activity = {activity_type:'revised_offer_contract_decision_dispatch_controller',subject:'WF-340 ' + (dealId ?? 'unknown-deal'),deal_id:dealId,lead_id:leadId,property_id:propertyId,status:action,decision,next_workflow:nextWorkflow,offer_price:offerPrice,dynamic_mao:dynamicMao,channel,recipient,dispatch_id:dispatchId,idempotency_key:idempotencyKey,reengagement,human_review_required:humanReviewRequired,asset_type:assetType,asset_strategy:assetStrategy,hard_mao_guardrail:true,dnc,blockers,reason};
return [{json:{...input,wf_id:'WF-340',action,next_workflow:nextWorkflow,dispatch_ready:dispatchReady,reengagement,human_review_required:humanReviewRequired,dynamic_mao:dynamicMao,offer_price:offerPrice,channel,recipient,dispatch_id:dispatchId,idempotency_key:idempotencyKey,asset_type:assetType,asset_strategy:assetStrategy,hard_mao_guardrail:true,reason,crm_activity:activity,evaluated_at:new Date().toISOString()}}];
